import {mountCardThumbnails} from './card-thumbnails.mjs?v=0.9.1';
import {pickQuickFiles,screenshotBuild,QUICK_IMAGE_LIMIT} from './quick-posts.mjs?v=0.9.0';
import {gameSkills,resolveReservation,reservationError,toggleReservation,reconcileReservations,MAX_RESERVATIONS,SKILL_SLOT_LABELS} from './skill-reservations.mjs?v=0.9.0';
import {createClient} from './vendor/supabase.mjs';
import {SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY} from './guild-config.mjs';
import {blankGuide,blankMatchup,STAT_FIELDS,validateGuide,filterGuides,canEdit,safeHttps} from './guild-model.mjs?v=0.9.0';
import {HERO_TYPES,heroesByType,preservedChoices,availableLegendaryPets,mixedSetDescription} from './guide-options.mjs?v=0.9.0';
const db=createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{flowType:'pkce',detectSessionInUrl:true}});
const $=s=>document.querySelector(s),root=$('#guild-app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={quick:null,setupPending:false,user:null,providerToken:null,access:null,guild:null,member:null,members:[],guides:[],view:'list',guide:null,comments:[],attachments:[],edit:null,dirty:false,busy:false,syncing:false,search:'',mine:false,enemy:['','',''],heroTypes:{},urls:[],generation:0};
let stopCardThumbnails=()=>{};
let D,H,C,K,heroes,pets=[],sets=[],accessories=[],authVersion=0,verifyPromise=null,retryAt=0,lastAttempt=0,providerUser=null,suspendedEdit=null;
function rememberToken(session){if(!session)return;if(providerUser!==session.user.id){S.providerToken=null;providerUser=session.user.id;}const key='gvg-discord:'+session.user.id;try{if(session.provider_token)sessionStorage.setItem(key,session.provider_token);S.providerToken=session.provider_token||S.providerToken||sessionStorage.getItem(key);}catch{S.providerToken=session.provider_token||S.providerToken;}}
const roleText=r=>({viewer:'可查看攻略',editor:'攻略投稿者',admin:'公會管理員'}[r]||'尚未驗證');
const heroName=id=>H?.get(id)?.name_tw||id||'未選擇';
const formText=f=>({s6:'未覺醒',awakened:'覺醒',source_default:'來源預設'}[f]||f);
function heroPortrait(h){return K?.heroes?.[h.id]?.portraits?.[h.form]||`assets/heroes/${h.id}.webp`;}
const person=(h,{compact=false}={})=>`<div class="guild-person"><img src="${esc(heroPortrait(h))}" alt="${esc(heroName(h.id))}" loading="lazy"><span>${esc(heroName(h.id))}${attackOrderBadges(h)}${compact?'':`<small>${esc(formText(h.form))}${h.row?' · '+(h.row==='front'?'前排':'後排'):''}</small>`}</span></div>`;
function team(hs,formation='',{pet='',compact=false}={}){const f=C.formations.find(f=>f.name===formation);return `<div class="formation-board" aria-label="${esc(formation||'隊伍站位')}"><div class="formation-heading">${esc(formation||'未指定陣型')}${f?`<span>原始槽位：前${f.front}／後${f.back}</span><span class="actual-formation-count">本隊${hs.filter(h=>h.id).length}人：前${hs.filter(h=>h.id&&(h.row||'front')==='front').length}／後${hs.filter(h=>h.id&&h.row==='back').length}</span>`:''}</div><div class="formation-content ${pet?'with-pet':''}">${['back','front'].map(row=>`<div class="formation-row"><span class="row-label">${row==='front'?'前排':'後排'}</span>${hs.filter(h=>(h.row||'front')===row).map(h=>person(h,{compact})).join('')||'<span class="empty-row">—</span>'}</div>`).join('')}${pet?`<div class="formation-pet"><span class="row-label">寵物</span>${petImage(pet)||'<span class="pet-art-unavailable" aria-hidden="true">寵</span>'}<span class="formation-pet-name">${esc(pet)}</span></div>`:''}</div></div>`;}
function matchupPreview(m,i){return `<div class="guild-matchup-preview"><span class="matchup-label">應對 ${i+1}</span><div class="matchup-heroes">${m.heroes.map(h=>`<span class="matchup-hero"><img src="${esc(heroPortrait(h))}" alt="${esc(heroName(h.id))}" loading="lazy"><span>${esc(heroName(h.id))}</span></span>`).join('')}</div></div>`;}
const options=(items,current,empty='請選擇')=>`<option value="">${empty}</option>`+items.map(([value,label])=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`).join('');
const heroOptions=(id,type=null)=>options((type===null?heroes:heroesByType(heroes,type)).map(h=>[h.hero_id,h.name_tw]),id,type===null?'選擇角色':type?'選擇角色 · 新 → 舊':'請先選擇類型');
const heroType=(path,id)=>H.get(id)?.role_en||S.heroTypes[path]||'';
function visualSelect(label,path,current,entries,{role=false,extra='',disabled=false,empty='請選擇'}={}){return `<div class="guild-field visual-field"><span>${label}</span><select class="visual-native" ${role?`data-role-path="${path}"`:`data-path="${path}"`} aria-label="${label}" ${extra} ${disabled?'disabled':''}>${options(entries.map(x=>[x.value,x.label]),current,empty)}</select><details class="visual-picker" ${disabled?'inert':''}><summary>${entries.find(x=>x.value===current)?.icon?`<img src="${esc(entries.find(x=>x.value===current).icon)}" alt="">`:''}<span>${esc(entries.find(x=>x.value===current)?.label||empty)}</span><span class="set-chevron">⌄</span></summary><div class="visual-options" role="listbox" aria-label="${label}">${[{value:'',label:empty},...entries].map(x=>`<button type="button" role="option" aria-selected="${x.value===current}" data-g="visual-select" data-value="${esc(x.value)}">${x.icon?`<img src="${esc(x.icon)}" alt="" loading="lazy">`:''}<span>${esc(x.label)}</span></button>`).join('')}</div></details></div>`;}
function rolePicker(label,path,id){return visualSelect(label,path,heroType(path,id),HERO_TYPES.map(([value,label])=>({value,label,icon:C.role_icons?.[value]})),{role:true,empty:'先選角色類型'});}
function teamHeroPicker(label,path,h,change){const type=heroType(path,h.id);return `<div class="role-hero-picker">${rolePicker('角色類型',path,h.id)}${visualSelect(label+' *',path+'.id',h.id,heroesByType(heroes,type).map(x=>({value:x.hero_id,label:x.name_tw,icon:`assets/heroes/${x.hero_id}.webp`})),{extra:change,disabled:!type,empty:type?'選擇角色 · 新 → 舊':'請先選擇類型'})}</div>`;}
function rowPicker(h,i,group,path){const f=C.formations.find(f=>f.name===group.formation);return `<label class="guild-field"><span>站位</span><select data-path="${path}.row">${['front','back'].map(row=>{const full=f&&group.heroes.filter((x,j)=>j!==i&&x.id&&x.row===row).length>=f[row];return `<option value="${row}" ${h.row===row?'selected':''} ${full?'disabled':''}>${row==='front'?'前排':'後排'}${full?'（已滿）':''}</option>`}).join('')}</select></label>`;}
function formationError(group){const f=C.formations.find(f=>f.name===group.formation);return f&&['front','back'].some(row=>group.heroes.filter(h=>h.id&&(h.row||'front')===row).length>f[row])?'目前站位超過陣型人數，請調整前後排後再儲存。':'';}
function equipmentSelect(label,path,current,items=[]){return selectField(label,path,current,preservedChoices(items.map(x=>[x.key,x.label]),current));}
function attackOrderBadges(h){return `<span class="attack-order-badges">${h.attack_order?`<span>我方 ${esc(h.attack_order)} 速</span>`:''}${h.global_attack_order?`<span class="global-speed">全場 ${esc(h.global_attack_order)} 速（必要）</span>`:''}</span>`;}
function attackOrderEditor(h,base){return `<div class="attack-order-editor">${selectField('我方三人普攻順序',base+'.attack_order',h.attack_order||'',[1,2,3].map(n=>[String(n),`我方第${n}速`]))}${selectField('全場六人順位（必要條件，選填）',base+'.global_attack_order',h.global_attack_order||'',[1,2,3,4,5,6].map(n=>[String(n),`必須全場第${n}速`]))}<p class="guild-small">我方順序只比較這三人；全場順位包含敵方三人。這是普攻先後要求，與技能預約分開；實際請核對雙方攻速。</p></div>`;}
function attackOrderSummary(hs){const own=hs.filter(h=>h.attack_order).sort((a,b)=>Number(a.attack_order)-Number(b.attack_order)),all=hs.filter(h=>h.global_attack_order).sort((a,b)=>Number(a.global_attack_order)-Number(b.global_attack_order));return own.length||all.length?`<div class="attack-order-summary"><h3>普攻速度順序</h3>${own.length?`<p>我方：${own.map(h=>`${esc(heroName(h.id))}（${esc(h.attack_order)}速）`).join(' → ')}</p>`:''}${all.length?`<p class="required">必要全場順位：${all.map(h=>`${esc(heroName(h.id))}＝${esc(h.global_attack_order)}速`).join('；')}</p>`:''}<small>全場順位含敵方三人；未填的順位不代表已確認。</small></div>`:'';}
function accessoryChoiceEditor(h,base){const e=C.equipment,kind=h.accessory_kind||'any',rarity=h.accessory_rarity||'any';const effects=e.accessory_effects.filter(x=>kind==='compound'||rarity==='any'||x.rarity===rarity).map(x=>[x.key,`${e.accessory_rarities.find(r=>r.key===x.rarity)?.label||''} · ${x.label}${x.effect?' — '+x.effect:''}`]);return `<div class="accessory-editor">${selectField('飾品稀有度',base+'.accessory_rarity',rarity,[['any','不限'],...e.accessory_rarities.map(x=>[x.key,x.label])])}${selectField('戒指需求',base+'.accessory_kind',kind,[['any','一般／復合都可以'],['normal','一般戒指'],['compound','復合戒指']])}${selectField(kind==='compound'?'復合效果 1':'飾品效果',base+'.accessory_effect_1',h.accessory_effect_1||'',preservedChoices(effects,h.accessory_effect_1))}${kind==='compound'?selectField('復合效果 2',base+'.accessory_effect_2',h.accessory_effect_2||'',preservedChoices(effects,h.accessory_effect_2)):''}${[h.accessory_effect_1,...(kind==='compound'?[h.accessory_effect_2]:[])].map(key=>e.accessory_effects.find(x=>x.key===key)).filter(x=>x?.effect).map(x=>`<p class="guild-small ring-effect-note">${esc(x.label)}：${esc(x.effect)}</p>`).join('')}${h.accessory?`<p class="guild-small">原攻略補充：${esc(h.accessory)}</p>`:''}</div>`;}
function accessoryEditor(h,base){const alts=h.accessory_alternatives||[],i=base.split('.').at(-1);return `<section class="ring-priorities"><h3>戒指首選</h3>${accessoryChoiceEditor(h,base)}${alts.map((a,j)=>`<div class="ring-alternative"><h3>${j===0?'戒指次選':'戒指第三選擇'}</h3>${accessoryChoiceEditor(a,`${base}.accessory_alternatives.${j}`)}<button type="button" class="soft-btn" data-g="ring-remove" data-i="${i}" data-j="${j}">移除此替代方案</button></div>`).join('')}${alts.length<2?`<button type="button" class="soft-btn" data-g="ring-add" data-i="${i}">＋ ${alts.length?'新增第三選擇':'新增次選戒指'}</button>`:''}</section>`;}
function exclusiveEditor(h,base){return `${equipmentSelect('專屬裝備調律屬性',base+'.exclusive',h.exclusive,C.equipment.exclusive_tuning)}<small class="guild-small">調律屬性為共用選項；角色專屬技能依遊戲內裝備。</small>`;}
function equipmentDescription(h,k){const e=C.equipment;if(k==='weapon'||k==='armor')return e[k+'_main'].find(x=>x.key===h[k])?.label||h[k]||'未指定';if(k==='exclusive')return e.exclusive_tuning.find(x=>x.key===h[k])?.label||h[k]||'未指定';if(k==='accessory'&&h.accessory_alternatives?.length){const primary={...h,accessory_alternatives:[]};return ['首選：'+equipmentDescription(primary,'accessory'),...h.accessory_alternatives.map((a,j)=>(j===0?'次選：':'第三選擇：')+equipmentDescription(a,'accessory'))].join('\n');}if(k==='accessory'){const labels=[e.accessory_rarities.find(x=>x.key===h.accessory_rarity)?.label||'不限稀有度',({normal:'一般戒指',compound:'復合戒指',any:'一般／復合都可'}[h.accessory_kind]||'一般／復合都可'),...[h.accessory_effect_1,...(h.accessory_kind==='compound'?[h.accessory_effect_2]:[])].filter(Boolean).map(key=>e.accessory_effects.find(x=>x.key===key)?((e.accessory_effects.find(x=>x.key===key).label)+(e.accessory_effects.find(x=>x.key===key).effect?' — '+e.accessory_effects.find(x=>x.key===key).effect:'')):key)];return h.accessory_kind||h.accessory_effect_1?labels.join(' · '):h.accessory||'未指定';}return h[k]||'未指定';}
function warning(text){return text?`<aside class="strategy-warning"><strong>⚠ 特別注意事項</strong><div>${esc(text)}</div></aside>`:'';}
function reservationBoard(hs,queue,index,{editable=false}={}){
 return `<div class="reservation-board" data-queue-scope="${esc(index)}">${hs.map((h,slot)=>{
  const skills=gameSkills(h,K);return `<article class="reservation-hero"><div class="reservation-portrait ${h.id?'':'is-empty'}">${h.id?`<img src="${esc(K.heroes[h.id]?.portraits?.[h.form]||`assets/heroes/${h.id}.webp`)}" alt="${esc(heroName(h.id))}" loading="lazy">`:'<span>選擇角色</span>'}</div><div class="reservation-hero-name">${esc(h.id?heroName(h.id):`角色 ${slot+1}`)}<small>${h.id?esc(formText(h.form)):''}</small></div><div class="reservation-skills">${skills.map(skill=>{
   const positions=queue.flatMap((q,j)=>q.hero_id===h.id&&q.skill===skill.key?[j+1]:[]),label=skill.name_tw||skill.name_en||skill.label;return `<${editable?'button':'div'} ${editable?'type="button"':''} class="reservation-skill ${positions.length?'is-reserved':''}" data-skill-slot="${esc(skill.key)}" ${editable?`data-g="skill-toggle" data-i="${esc(index)}" data-hero="${esc(h.id)}" data-skill="${esc(skill.key)}" aria-pressed="${positions.length>0}" aria-label="${esc(heroName(h.id)+' · '+skill.label+' · '+label+(positions.length?' · 取消預約':' · 加入預約'))}"`:''} title="${esc(skill.label+' · '+label)}">${skill.icon?`<img src="${esc(skill.icon)}" alt="${esc(label)}" loading="lazy">`:`<span>${esc(skill.label)}</span>`}<span class="reservation-slot">${esc(skill.label)}</span>${positions.length?`<span class="reservation-badge">預約${positions.join('、')}</span>`:''}</${editable?'button':'div'}>`;
  }).join('')||'<span class="reservation-no-skills">選好角色後顯示技能</span>'}</div></article>`;
 }).join('')}</div>`;
}
function queueHeroes(index){return index==='general'?S.edit.build.heroes:S.edit.build.matchups[+index].heroes;}
function queueEditor(queue,path,index){const my=queueHeroes(index);return `<section class="skill-reservation-editor"><div class="reservation-heading"><h3>${index==='general'?'我方':'敵方'}技能順序預約</h3><span>${queue.length}／${MAX_RESERVATIONS} 手</span></div><p class="guild-small">點技能加入預約，再點一次取消。由上往下固定為覺醒技、技能2、技能1；未覺醒角色不顯示覺醒技。</p>${reservationBoard(my,queue,index,{editable:true})}${queueTimeline(queue,my,index,{editable:true})}</section>`;}
function queueTimeline(queue,my,index,{editable=false}={}){if(!queue.length)return '<p class="guild-small reservation-empty">尚未預約技能。</p>';return `<ol class="reservation-timeline">${queue.map((q,j)=>{const skill=resolveReservation(q,my,K);return `<li class="${skill?'':'invalid-reservation'}"><span class="reservation-number">預約${j+1}</span>${skill?.icon?`<img src="${esc(skill.icon)}" alt="">`:''}<span class="reservation-step-name">${esc(heroName(q.hero_id))}<small>${esc(skill?(skill.name_tw||skill.name_en||skill.label):'此技能不適用目前角色型態，請移除或重新選擇')}</small></span>${editable?`<span class="reservation-controls"><button type="button" class="soft-btn" data-g="queue-up" data-i="${esc(index)}" data-j="${j}" ${j===0?'disabled':''} aria-label="提前預約${j+1}">↑</button><button type="button" class="soft-btn" data-g="queue-down" data-i="${esc(index)}" data-j="${j}" ${j===queue.length-1?'disabled':''} aria-label="延後預約${j+1}">↓</button><button type="button" class="soft-btn" data-g="queue-remove" data-i="${esc(index)}" data-j="${j}" aria-label="移除預約${j+1}">×</button></span>`:''}</li>`;}).join('')}</ol>`;}
function queueDisplay(queue,my=S.guide?.build.heroes||[],enemy=false){return `<section class="skill-reservation-display"><h3>${enemy?'敵方':'我方'}技能順序預約</h3>${reservationBoard(my,queue||[],'display')}${queueTimeline(queue||[],my,'display')}</section>`;}
function reconcileGuideQueues(){if(!S.edit)return;const b=S.edit.build;b.queue=reconcileReservations(b.queue,b.heroes,K);b.matchups.forEach(m=>{m.queue=reconcileReservations(m.queue,b.heroes,K);m.enemy_queue=reconcileReservations(m.enemy_queue,m.heroes,K)});}
function formationPicker(current){return selectField('陣型','build.formation',current,preservedChoices(C.formations.map(f=>[f.name,`${f.name} · 槽位上限：前${f.front}／後${f.back}`]),current));}
function petImage(name){const pet=C.legendary_pets.find(p=>p.name_tw===name);return pet?`<img class="pet-option-image" src="${esc(pet.icon)}" alt="${esc(pet.name_tw)}" width="40" height="40">`:'';}
function petPicker(current){const list=preservedChoices(availableLegendaryPets(C).map(p=>[p.name_tw,p.name_tw]),current);return `<label class="guild-field"><span>寵物 *</span><select data-path="build.pet.name">${options(list,current,'選擇傳說寵物')}</select><span id="selected-pet-art">${petImage(current)}</span><small class="guild-small">已收錄 ${C.legendary_pets.length} 隻已推出傳說寵物</small></label>`;}
function setIcon(name){const item=C.sets.find(x=>x.name===name);return item?`<img class="set-icon" src="${esc(item.icon)}" alt="${esc(item.name)}套裝圖示" width="32" height="32">`:name==='雜套'?'<span class="mixed-set-icon" aria-hidden="true"><span class="mixed-star">★</span></span>':'<span class="set-icon-empty" aria-hidden="true"></span>';}
function setPicker(h,i){const entries=preservedChoices([...C.sets.map(x=>[x.name,x.name]),['雜套','雜套']],h.set);return `<div class="guild-field set-field"><span id="set-label-${i}">套裝建議</span><details class="set-picker" data-set-index="${i}"><summary aria-labelledby="set-label-${i} set-value-${i}">${setIcon(h.set)}<span id="set-value-${i}">${esc(h.set||'選擇套裝')}</span><span class="set-chevron" aria-hidden="true">⌄</span></summary><div class="set-options" role="listbox" aria-label="角色${i+1}套裝建議">${[['','未指定套裝'],...entries].map(([value,label])=>`<button type="button" role="option" aria-selected="${h.set===value}" data-g="set-select" data-i="${i}" data-value="${esc(value)}">${setIcon(value)}<span>${esc(label)}${value==='雜套'?'<small>多套裝混搭，優先指定素質</small>':''}</span>${h.set===value?'<span aria-hidden="true">✓</span>':''}</button>`).join('')}</div></details>${h.set==='雜套'?`${selectField('雜套優先素質',`build.heroes.${i}.mixed_stat`,h.mixed_stat||'',STAT_FIELDS)}<small class="guild-small">從不同套裝挑選這項素質最高的裝備，不要求湊齊同套裝。</small>`:''}</div>`;}
const forms=(id,current)=>options([...new Set((D.skills||[]).filter(s=>s.hero_id===id).map(s=>s.form))].map(f=>[f,formText(f)]),current,'選擇型態');
function field(label,path,value,{type='text',max=1000,list='',hint='',required=false}={}){return `<label class="guild-field"><span>${label}${required?' *':''}</span>${type==='textarea'?`<textarea data-path="${path}" maxlength="${max}" rows="3">${esc(value)}</textarea>`:`<input data-path="${path}" type="${type}" value="${esc(value)}" maxlength="${max}" ${list?`list="${list}"`:''} ${required?'required':''}>`}${hint?`<small class="guild-small">${hint}</small>`:''}</label>`}
const selectField=(label,path,value,items)=>`<label class="guild-field"><span>${label}</span><select data-path="${path}">${options(items,value)}</select></label>`;
function toast(t){$('#guild-toast').textContent=t;$('#guild-toast').classList.add('show');setTimeout(()=>$('#guild-toast').classList.remove('show'),3000)}
function releaseImages(){stopCardThumbnails();S.urls.forEach(URL.revokeObjectURL);S.urls=[];}
function clearPrivate(){releaseQuick();suspendedEdit=null;document.querySelector('#viewer-watermark')?.remove();S.generation++;releaseImages();S.access=null;S.member=null;S.guild=null;S.members=[];S.guides=[];S.guide=null;S.comments=[];S.attachments=[];S.edit=null;S.dirty=false;S.view='list';}
function suspendPrivate(message){const draft=S.quick?{quick:S.quick,user:S.user?.id,dirty:S.dirty}:S.edit?{guide:S.edit,user:S.user?.id,dirty:S.dirty}:suspendedEdit;clearPrivate();suspendedEdit=draft;lockPage(message);}
function restoreEditor(){if(suspendedEdit?.user===S.user?.id&&['admin','editor'].includes(S.access?.role)){if(suspendedEdit.quick){S.quick=suspendedEdit.quick;S.quick.files.forEach(x=>x.url=URL.createObjectURL(x.file));S.view='quick';}else{S.edit=suspendedEdit.guide;S.view='edit';}S.dirty=suspendedEdit.dirty;suspendedEdit=null;toast('已恢復連線，尚未儲存的攻略仍保留在本頁');}}
function errorText(e){const msg=e?.message||String(e||'');if(/does not exist|schema cache|PGRST|Failed to send a request|Failed to fetch|permission denied for schema/i.test(msg))return '公會資料庫或驗證服務尚未啟用。設定完成後請重新驗證。';if(/row-level security|permission denied|42501/i.test(msg))return '權限不足或驗證已過期，請重新驗證 Discord 身分。';return msg.slice(0,260)||'操作未完成，請稍後再試。'}
function showError(e){toast(errorText(e));const slot=$('#guild-form-error');if(slot)slot.textContent=errorText(e);}
function lockPage(message='請用 Discord 驗證你的公會身分。'){
 if(S.setupPending)message='Discord 登入尚未啟用，公會攻略暫時鎖定。公開出刀建議仍可使用。';
 root.innerHTML=`<section class="guild-auth panel"><span class="eyebrow">GUILD STRATEGIES · 公會攻略</span><div class="guild-hero"><span class="guild-pill">僅限指定 Discord 身分組</span><h1>把關鍵打法，留在公會裡。</h1><p>三人陣容、寵物、角色配裝與應對條件，由公會一起累積。</p></div><div class="guild-note" role="status">${esc(message)}</div><button class="primary" data-g="login" ${S.setupPending?'disabled':''}>${S.setupPending?'等待 Discord 設定':S.user?'重新驗證 Discord':'使用 Discord 登入'}</button>${S.user?'<button class="soft-btn" data-g="logout">登出</button>':''}<div class="guild-permissions"><div><b>公會成員</b><p>有指定身分組即可查看攻略、搜尋敵隊與回報實戰。</p></div><div><b>公會成員一起投稿</b><p>有投稿身分組即可新增攻略、編輯自己的攻略及上傳截圖。</p></div></div><p class="guild-small guild-submit">無須另辦帳密。登入不代表取得權限，仍須通過伺服器與身分組檢查。<br><a href="index.html">← 回到公開出刀建議</a></p></section>`;
}
async function login(){
 if(S.dirty&&!confirm('尚未儲存的攻略會遺失，確定重新登入？'))return;
 const {error}=await db.auth.signInWithOAuth({provider:'discord',options:{scopes:'identify email guilds.members.read',redirectTo:new URL('guild.html',location.href).href.split('?')[0]}});
 if(error)showError(error);
}
async function verify({silent=false,force=false}={}){
 if(verifyPromise)return verifyPromise;
 if(!force&&S.access&&Date.parse(S.access.checked_until)>Date.now()+45000)return true;
 if(Date.now()<retryAt){if(!silent)toast(`Discord 暫時忙碌，${Math.ceil((retryAt-Date.now())/1000)} 秒後自動重試`);return false;}
 verifyPromise=(async()=>{S.syncing=true;lastAttempt=Date.now();
 try{
  const {data:{session}}=await db.auth.getSession();
  if(!session){clearPrivate();lockPage();return false;}
  S.user=session.user;rememberToken(session);
  if(!S.providerToken){clearPrivate();lockPage('請重新以 Discord 登入，以恢復公會身分驗證。');return false;}
  const generation=S.generation;
  const {data,error}=await db.functions.invoke('discord-access',{body:{provider_token:S.providerToken}});
  if(generation!==S.generation)return false;
  if(error){let body={};try{body=await error.context.json()}catch{}const code=body.error;
   if(['discord_busy','discord_unavailable','verification_failed'].includes(code)||!code){retryAt=Date.now()+Math.max(10,Number(body.retry_after)||15)*1000;throw new Error('Discord 暫時無法連線，系統將自動重試。');}
   if(['discord_relogin_required','identity_mismatch','discord_login_required','not_authenticated'].includes(code)){clearPrivate();lockPage('Discord 登入憑證已失效，請重新登入。');return false;}
   throw new Error(code==='setup_required'?'Discord 公會驗證尚未設定完成。':'公會驗證服務目前無法使用。');
  }
  retryAt=0;
  if(!data?.allowed){clearPrivate();lockPage('目前沒有查看資格。請確認仍在公會 Discord 並持有攻略身分組。');return false;}
  const previousRole=S.access?.role;S.access=data;
  if(previousRole&&previousRole!==data.role&&S.edit){S.edit=null;S.dirty=false;S.view='list';toast('身分組權限已更新，已關閉編輯畫面');}
  return true;
 }catch(e){if(!S.access||Date.parse(S.access.checked_until)<=Date.now()){suspendPrivate(errorText(e));}else if(!silent)toast(errorText(e));return false;}
 finally{S.syncing=false;verifyPromise=null;}
 })();return verifyPromise;
}
async function loadGuild(){
 const generation=S.generation;
 const [{data:g,error:ge},{data:ms,error:me},{data:gs,error:se}]=await Promise.all([db.from('gvg_guilds').select('*').eq('id',S.access.guild_id).single(),db.from('gvg_members').select('user_id,nickname,role,status,guild_id').eq('guild_id',S.access.guild_id),db.from('gvg_guides').select('*').eq('guild_id',S.access.guild_id).order('updated_at',{ascending:false}).limit(500)]);
 if(ge||me||se)throw ge||me||se;if(generation!==S.generation)return;
 S.guild=g;S.members=ms;S.member=ms.find(m=>m.user_id===S.user.id);S.guides=gs;
 if(!S.member)throw new Error('公會資格已失效，請重新驗證。');
}
function watermark(){if(!S.member)return;let layer=document.querySelector('#viewer-watermark');if(!layer){layer=document.createElement('div');layer.id='viewer-watermark';layer.setAttribute('aria-hidden','true');document.body.append(layer);}const dc=S.user?.identities?.find(i=>i.provider==='discord')?.identity_data;const label=`${S.member.nickname} · ${dc?.provider_id||dc?.sub||S.user.id.slice(0,8)}`;layer.replaceChildren(...Array.from({length:30},()=>{const span=document.createElement('span');span.textContent=label;return span;}));}
let onlineMembers=[];
async function updatePresence(){if(!S.access||!S.guild||document.hidden||!db.rpc)return;const generation=S.generation;try{await db.rpc('gvg_presence_heartbeat',{p_guild:S.access.guild_id});const {data,error}=await db.rpc('gvg_online_members',{p_guild:S.access.guild_id});if(error||generation!==S.generation)return;onlineMembers=data||[];paintPresence();}catch{}}
function paintPresence(){const slot=$('#online-members');if(slot)slot.innerHTML=`<b>${onlineMembers.filter(m=>m.online).length} 位網站在線</b><span class="online-list">${onlineMembers.map(m=>`<span class="${m.online?'is-online':'is-offline'}">● ${esc(m.nickname)}${m.online?'':'（離線）'}</span>`).join('')}</span>`;}
setInterval(updatePresence,30000);
function header(){return `<div class="guild-topline"><div><span class="eyebrow">DISCORD VERIFIED · 公會內部</span><h1>${esc(S.guild.name)}</h1></div><div class="guild-actions"><span class="badge gold">${esc(roleText(S.access.role))}</span><span class="guild-small">${esc(S.member.nickname)}</span><button class="soft-btn" data-g="refresh">重新驗證</button><button class="soft-btn" data-g="logout">登出</button></div></div>`;}
function render(){if(!S.guild||!S.access)return lockPage();if(S.view==='quick')renderQuickEditor();else if(S.view==='edit')renderEditor();else if(S.view==='detail')renderDetail();else renderList();}
function renderList(){watermark();
 root.innerHTML=header()+`<div class="guild-layout"><aside class="panel guild-side"><span class="guild-pill">攻略由後端限制存取</span><h2>公會自己的解法</h2><p>同一隊可以有不同打法。查看每組敵隊的出技、速度與替換條件，再決定怎麼打。</p>${['admin','editor'].includes(S.access.role)?'<button class="primary" data-g="new">＋ 新增出刀攻略</button><button class="primary quick-new-btn" data-g="quick-new"><span class="quick-new-icon" aria-hidden="true">📷</span> 快速截圖投稿</button>':'<p>你可以查看攻略與回報實戰；新增攻略依公會設定的投稿身分組開放。</p>'}<button class="soft-btn" data-g="mine">${S.mine?'查看全公會':'只看我的攻略'}</button><p><span id="online-members">在線成員載入中…</span><br>目前身分：${esc(roleText(S.access.role))}</p><a href="index.html">公開出刀建議 ↗</a></aside><section><div class="guild-toolbar"><label class="search-box"><input id="guild-search" placeholder="搜尋攻略、角色或打法…" value="${esc(S.search)}" aria-label="搜尋公會攻略"></label><button class="soft-btn" data-g="reload">更新攻略</button></div><details class="guild-form-section" ${S.enemy.some(Boolean)?'open':''}><summary>依敵方角色篩選</summary><div class="guild-filter">${S.enemy.map((id,i)=>{const path=`filter.${i}`,type=heroType(path,id);return `<div>${rolePicker(`敵方${i+1}類型`,path,id)}<label class="guild-field"><span>敵方角色 ${i+1}</span><select data-filter-enemy="${i}" ${type?'':'disabled'}>${heroOptions(id,type)}</select></label></div>`}).join('')}</div><button class="soft-btn" data-g="reset-filter">清除角色篩選</button></details><div id="guild-guide-list"></div><p class="guild-small">最多載入最近500篇。草稿只限作者與管理員查看；公會資料不儲存到本機攻略庫。</p></section></div>`;
 renderCards();paintPresence();updatePresence();
}
function renderCards(){stopCardThumbnails();const generation=S.generation;const gs=filterGuides(S.guides,{text:S.search,enemy:S.enemy.filter(Boolean),mine:S.mine,userId:S.user.id},heroName);$('#guild-guide-list').innerHTML=`<p class="guild-small">${gs.length} 篇符合條件的攻略</p>`+(gs.length?gs.map(g=>`<article class="guild-card"><button class="guild-card-link" data-g="open" data-id="${esc(g.id)}"><span class="badge ${g.status==='draft'?'muted':'gold'}">${g.status==='draft'?'草稿・未發布':'公會內部'}</span><h2>${esc(g.title)}</h2>${g.build.kind==='screenshots'?`<div class="quick-card-preview"><b>📷 截圖快報 · ${Number(g.build.quick_count)||0} 張</b><span class="quick-card-thumbs" data-thumb-guide="${esc(g.id)}" data-thumb-count="${Number(g.build.quick_count)||0}">縮圖載入中…</span><p>${esc((g.summary||'點開查看公會截圖').slice(0,180))}</p></div>`:`${team(g.build.heroes,g.build.formation,{pet:g.build.pet.name,compact:true})}${warning(g.build.special_notes)}<div class="guild-card-matchups"><p>${g.build.matchups.length} 組應對組合</p>${g.build.matchups.map(matchupPreview).join('')}</div>`}<div class="guide-author">${esc(S.members.find(m=>m.user_id===g.author_id)?.nickname||'原公會成員')} · ${new Date(g.updated_at).toLocaleDateString('zh-TW')}</div></button></article>`).join(''):'<div class="guild-empty">沒有符合的攻略。可以調整篩選，或由投稿者新增第一篇。</div>');stopCardThumbnails=mountCardThumbnails($('#guild-guide-list'),db,{isAllowed:()=>generation===S.generation&&S.view==='list'&&!!S.access&&Date.parse(S.access.checked_until)>Date.now()});}
function dataLists(){return `<datalist id="pets">${pets.map(p=>`<option value="${esc(p)}">`).join('')}</datalist><datalist id="accessories">${accessories.map(p=>`<option value="${esc(p)}">`).join('')}</datalist>`;}
function renderEditor(){stopCardThumbnails();watermark();const g=S.edit;
 root.innerHTML=`<section class="guild-editor"><div class="guild-topline"><div><span class="eyebrow">GUILD GUIDE · ${g.id?'編輯':'新增'}攻略</span><h1>${g.id?'調整你的出刀攻略':'留下這一隊的解法。'}</h1></div><div class="guild-actions"><button class="soft-btn" data-g="back">取消</button><button class="soft-btn" data-g="save" data-status="draft">儲存草稿</button><button class="primary" data-g="save" data-status="published">發布至公會</button></div></div><div class="guild-note">僅同公會的指定 Discord 身分組可查看。草稿須填完整三人陣容與至少一組敵隊，再儲存；尚未儲存的內容只留在本頁。</div><div id="guild-form-error" class="guild-form-error" role="alert"></div><div class="guild-form-section"><h2>01 · 攻略基本資料</h2>${field('攻略標題','title',g.title,{max:120,required:true})}${field('特別注意事項','build.special_notes',g.build.special_notes||'',{type:'textarea',max:3000,hint:'此欄會以醒目大字顯示在攻略卡片與內容最前面。'})}${field('打法說明','summary',g.summary,{type:'textarea',max:6000,hint:'寫下勝負關鍵、適用範圍及實戰觀察；不要把建議值當成保證門檻。'})}${field('實戰影片連結（選填）','video_url',g.video_url,{type:'url',max:2000,hint:'影片本身也須限制觀看權限，網站不會替外部影片加鎖。'})}</div><div class="guild-form-section"><h2>02 · 我方隊伍與寵物</h2><div class="guild-fields">${formationPicker(g.build.formation)}${petPicker(g.build.pet.name)}</div>${field('寵物養成／替代條件','build.pet.condition',g.build.pet.condition,{max:1000})}${formationError(g.build)?`<p class="guild-form-error">${formationError(g.build)}</p>`:''}${team(g.build.heroes.filter(h=>h.id),g.build.formation)}${g.build.heroes.map(editorHero).join('')}${queueEditor(g.build.queue||[],'build.queue','general')}</div><div class="guild-form-section"><h2>03 · 應對組合與特殊條件</h2><p>每組敵隊有自己的出技順序、速度條件與換裝限制。</p>${g.build.matchups.map(editorMatchup).join('')}<button class="soft-btn" data-g="add-matchup" ${g.build.matchups.length>=12?'disabled':''}>＋ 加入另一組敵方陣容</button></div><div class="guild-note">截圖：儲存後進入攻略內容頁，即可上傳公會專用圖片。</div><div class="guild-actions guild-submit"><button class="soft-btn" data-g="save" data-status="draft">儲存草稿</button><button class="primary" data-g="save" data-status="published">發布至公會</button></div>${dataLists()}</section>`;}
function editorHero(h,i){const base=`build.heroes.${i}`;return `<details open><summary>角色 ${i+1} · ${esc(heroName(h.id))}</summary><div class="guild-fields">${teamHeroPicker('角色',base,h,`data-hero-change="${i}"`)}<label class="guild-field"><span>型態 *</span><select data-path="${base}.form">${h.id?forms(h.id,h.form):'<option value="s6">請先選角色</option>'}</select></label>${rowPicker(h,i,S.edit.build,base)}${setPicker(h,i)}${attackOrderEditor(h,base)}</div><details><summary>素質條件 · 必要／建議</summary><p class="guild-small">空白代表作者沒有指定，不是0。可填「至少18000」、「高於對方」等明確條件。</p><div class="guild-stats">${STAT_FIELDS.map(([key,label])=>{const s=h.stats.find(x=>x.key===key);return `<label class="guild-stat-row"><span>${label}</span><input data-stat-hero="${i}" data-stat-key="${key}" value="${esc(s?.value||'')}" maxlength="100" aria-label="角色${i+1}${label}數值"><select data-stat-kind="${i}" data-stat-key="${key}" aria-label="角色${i+1}${label}條件種類"><option value="recommended" ${s?.kind!=='required'?'selected':''}>建議</option><option value="required" ${s?.kind==='required'?'selected':''}>必要</option></select></label>`}).join('')}</div></details><div class="guild-fields">${equipmentSelect('武器推薦主屬性',`${base}.weapon`,h.weapon,C.equipment?.weapon_main)}${equipmentSelect('防具推薦主屬性',`${base}.armor`,h.armor,C.equipment?.armor_main)}${field('副屬性建議',`${base}.substats`,h.substats)}${accessoryEditor(h,base)}${exclusiveEditor(h,base)}${field('裝備必要條件、替代方案與其他說明',`${base}.notes`,h.notes,{type:'textarea',max:2000})}</div></details>`;}
function editorMatchup(m,i){const base=`build.matchups.${i}`,my=S.edit.build.heroes.filter(h=>h.id);return `<details open><summary>應對組合 ${i+1} · ${m.heroes.map(h=>esc(heroName(h.id))).join('＋')}</summary>${selectField('敵方陣型',`${base}.formation`,m.formation||'',C.formations.map(f=>[f.name,`${f.name} · 槽位上限：前${f.front}／後${f.back}`]))}<div class="guild-fields">${m.heroes.map((h,j)=>`<div>${teamHeroPicker(`敵方角色 ${j+1}`,`${base}.heroes.${j}`,h,`data-enemy-change="${i},${j}"`)}<label class="guild-field"><span>敵方型態</span><select data-path="${base}.heroes.${j}.form">${h.id?forms(h.id,h.form):'<option value="s6">請先選角色</option>'}</select></label>${rowPicker(h,j,m,`${base}.heroes.${j}`)}</div>`).join('')}${visualSelect('敵方寵物（選填）',`${base}.pet`,m.pet,preservedChoices(pets.map(p=>[p,p]),m.pet).map(([value,label])=>({value,label,icon:C.legendary_pets.find(p=>p.name_tw===value)?.icon})))}${field('敵方寵物養成／配置限制',`${base}.pet_condition`,m.pet_condition||'',{max:1000})}</div>${formationError(m)?`<p class="guild-form-error">${formationError(m)}</p>`:''}${team(m.heroes.filter(h=>h.id),m.formation)}${field('適用條件／不能打的情況',`${base}.conditions`,m.conditions,{type:'textarea',max:3000})}${field('速度與先手必要條件',`${base}.speed`,m.speed,{type:'textarea',max:2000,hint:'例如甲速度 > 乙；須搶過敵方角色；未知條件請寫尚未確認。'})}${queueEditor(m.enemy_queue||[],`${base}.enemy_queue`,i)}${field('這組對局的換寵／換裝／替換條件',`${base}.adjustments`,m.adjustments,{type:'textarea',max:3000})}${S.edit.build.matchups.length>1?`<button class="soft-btn" data-g="remove-matchup" data-i="${i}">移除這組應對組合</button>`:''}</details>`;}
function getPath(obj,path){return path.split('.').reduce((o,k)=>o?.[k],obj)}
function setPath(obj,path,value){const keys=path.split('.'),last=keys.pop();let ptr=obj;for(const k of keys)ptr=ptr[k];ptr[last]=value;}
function stamp(){S.dirty=true;}
async function saveGuide(status){
 if(S.busy)return;S.edit.status=status;const rowError=[S.edit.build,...S.edit.build.matchups].map(formationError).find(Boolean);const queueError=[S.edit.build.queue||[],].map(q=>reservationError(q,S.edit.build.heroes,K)).concat(S.edit.build.matchups.map(m=>reservationError(m.enemy_queue||[],m.heroes,K))).find(Boolean);const problem=rowError||queueError||validateGuide(S.edit,new Set(heroes.map(h=>h.hero_id)));if(problem){$('#guild-form-error').textContent=problem;$('#guild-form-error').scrollIntoView({block:'center'});return;}
 const payload=structuredClone(S.edit);S.busy=true;root.querySelectorAll('[data-g="save"]').forEach(b=>b.disabled=true);
 try{
  if(!await verify())return;
  if(!['admin','editor'].includes(S.access.role))throw new Error('目前沒有投稿權限');
  let response;const fields={title:payload.title.trim(),summary:payload.summary,status,build:payload.build,video_url:payload.video_url.trim()};
  if(payload.id)response=await db.from('gvg_guides').update(fields).eq('id',payload.id).select().single();
  else response=await db.from('gvg_guides').insert({...fields,guild_id:S.access.guild_id,author_id:S.user.id}).select().single();
  if(response.error)throw response.error;S.dirty=false;S.edit=null;await loadGuild();await openGuide(response.data.id);toast(status==='draft'?'草稿已儲存，只有作者與管理員可見':'已發布至公會攻略');
 }catch(e){showError(e);}finally{S.busy=false;root.querySelectorAll('[data-g="save"]').forEach(b=>b.disabled=false);}
}
async function openGuide(id){
 releaseImages();const generation=S.generation;
 const {data,error}=await db.from('gvg_guides').select('*').eq('id',id).single();if(error)throw error;if(generation!==S.generation)return;
 S.guide=data;S.view='detail';S.comments=[];S.attachments=[];renderDetail();
 const [{data:cs,error:ce},{data:ats,error:ae}]=await Promise.all([db.from('gvg_comments').select('*').eq('guide_id',id).order('created_at'),db.from('gvg_attachments').select('*').eq('guide_id',id).order('created_at')]);
 if(generation!==S.generation||S.guide?.id!==id||S.view!=='detail')return;
 if(ce||ae)throw ce||ae;S.comments=cs;S.attachments=ats;renderDetail();await loadImages();window.scrollTo({top:0});
}
function renderDetail(){watermark();const g=S.guide;if(!g)return;const edit=canEdit(g,S.user.id,S.access.role);if(g.build.kind==='screenshots')return renderQuickDetail(g,edit);
 root.innerHTML=`<section class="guild-detail"><div class="guild-topline"><a href="guild.html" data-g="back">← 公會攻略</a><div class="guild-actions">${edit?'<button class="soft-btn" data-g="edit">編輯攻略</button><button class="soft-btn" data-g="delete">刪除攻略</button>':''}<button class="soft-btn" data-g="logout">登出</button></div></div><span class="badge gold">${g.status==='draft'?'草稿・限作者與管理員':'公會內部攻略'}</span><h1>${esc(g.title)}</h1>${warning(g.build.special_notes)}<div class="guide-author">${esc(S.members.find(m=>m.user_id===g.author_id)?.nickname||'原公會成員')} · 更新 ${new Date(g.updated_at).toLocaleString('zh-TW')}</div><div class="guild-form-section"><div class="guild-prose">${esc(g.summary||'作者未補充打法說明。')}</div>${safeHttps(g.video_url)?`<p><a href="${esc(g.video_url)}" target="_blank" rel="noopener noreferrer">查看實戰影片 ↗</a></p>`:''}</div><div class="guild-form-section"><h2>進攻陣容</h2>${team(g.build.heroes,g.build.formation)}${attackOrderSummary(g.build.heroes)}${queueDisplay(g.build.queue)}<div class="guild-note">陣型：${esc(g.build.formation||'未指定')}<br>寵物：${esc(g.build.pet.name)}${g.build.pet.condition?'\n'+esc(g.build.pet.condition):''}</div><div class="guild-build-grid">${g.build.heroes.map(h=>`<article>${person(h)}<h3>素質需求</h3>${h.stats.filter(s=>s.value).map(s=>`<p class="stat-line ${s.kind==='required'?'required':'recommended'}">${s.kind==='required'?'必要':'建議'} · ${esc(STAT_FIELDS.find(([k])=>k===s.key)?.[1]||s.key)}：${esc(s.value)}</p>`).join('')||'<p class="guild-small">未指定數值門檻</p>'}<dl>${[['set','套裝'],['weapon','武器'],['armor','防具'],['substats','副屬性'],['accessory','飾品'],['exclusive','專屬裝備'],['notes','必要條件／替代方案']].map(([k,l])=>`<dt>${l}</dt><dd>${k==='set'?`<span class="set-display">${setIcon(h.set)}${esc(mixedSetDescription(h,STAT_FIELDS))}</span>`:esc(equipmentDescription(h,k))}</dd>`).join('')}</dl></article>`).join('')}</div></div><div class="guild-form-section"><h2>應對組合</h2>${g.build.matchups.map((m,i)=>`<div class="guild-target"><h3>對局 ${i+1}</h3>${team(m.heroes,m.formation)}${m.pet?`<div class="guild-note">敵方寵物／配置：${esc(m.pet)}${m.pet_condition?' · '+esc(m.pet_condition):''}</div>`:''}<h3>適用條件</h3><p class="guild-prose">${esc(m.conditions||'作者未指定，請先核對實際敵方配置。')}</p><h3>速度與先手</h3><p class="guild-prose">${esc(m.speed||'作者未指定速度條件。')}</p>${queueDisplay(m.enemy_queue||[],m.heroes,true)}${m.queue?.length?`<details class="legacy-own-queue"><summary>此對局舊版我方預約（保留原資料）</summary>${queueDisplay(m.queue,g.build.heroes)}</details>`:''}${m.adjustments?`<h3>對局專用調整</h3><p class="guild-prose">${esc(m.adjustments)}</p>`:''}</div>`).join('')}</div><section class="guild-form-section"><h2>實戰截圖</h2><p class="guild-small">圖片同樣需要公會權限才能下載。</p><div class="guild-images">${S.attachments.map(a=>`<figure><div class="guild-loading" id="image-${esc(a.id)}">載入圖片…</div><figcaption>${esc(a.filename)} ${edit?`<button class="link-btn" data-g="image-delete" data-id="${esc(a.id)}">移除</button>`:''}</figcaption></figure>`).join('')}</div>${!S.attachments.length?'<p class="guild-small">尚未附上截圖。</p>':''}${edit?`<input class="guild-file" id="guild-upload" type="file" accept="image/png,image/jpeg,image/webp" aria-label="上傳攻略截圖" ${S.attachments.length>=12?'disabled':''}><p class="guild-small">單張上限5MB，最多12張，支援PNG／JPG／WebP。</p>`:''}</section><section class="guild-form-section"><h2>實戰回報與補充</h2><p class="guild-small">回報是個別實戰觀察，不會自動換算成保證勝率。</p>${S.comments.map(c=>`<article class="guild-comment"><div class="guild-comment-head"><span>${esc(c.nickname)} · ${c.result==='win'?'成功':c.result==='loss'?'失敗':'補充'} · ${new Date(c.created_at).toLocaleDateString('zh-TW')}</span>${c.author_id===S.user.id||S.access.role==='admin'?`<button class="link-btn" data-g="comment-delete" data-id="${esc(c.id)}">刪除</button>`:''}</div><p class="guild-prose">${esc(c.body)}</p></article>`).join('')}<form id="guild-comment-form"><label class="guild-field"><span>回報類型</span><select name="result"><option value="note">補充說明</option><option value="win">成功</option><option value="loss">失敗</option></select></label><label class="guild-field"><span>實戰配置、結果或注意事項</span><textarea name="body" maxlength="3000" required rows="3"></textarea></label><button class="soft-btn" type="submit">送出回報</button></form></section></section>`;}
function releaseQuick(){if(S.quick){S.quick.files.forEach(x=>URL.revokeObjectURL(x.url));S.quick=null;}}
function beginQuick(guide=null){releaseQuick();S.quick={id:guide?.id||null,title:guide?.title||'',summary:guide?.summary||'',files:[],existing:guide?structuredClone(S.attachments):[]};S.view='quick';S.edit=null;S.dirty=false;renderQuickEditor();$('#quick-dropzone')?.focus({preventScroll:true});}
function renderQuickEditor(){stopCardThumbnails();const q=S.quick;if(!q)return;watermark();root.innerHTML=`<section class="guild-editor"><div class="guild-topline"><div><span class="eyebrow">GUILD SCREENSHOTS</span><h1>快速截圖投稿</h1></div><div class="guild-actions"><button class="soft-btn" data-g="quick-cancel">取消</button><button class="primary" data-g="quick-publish" ${S.busy?'disabled':''}>${S.busy?'上傳中…':'發布截圖至公會'}</button></div></div><div class="guild-note">無須填寫角色或配裝。最多10張，每張5MB；僅通過公會驗證的成員可查看。</div><label class="guild-field"><span>標題（選填）</span><input data-quick="title" maxlength="120" value="${esc(q.title)}" placeholder="例如：今天實戰配置"></label><label class="guild-field"><span>簡短說明（選填）</span><textarea data-quick="summary" maxlength="6000" rows="3">${esc(q.summary)}</textarea></label><div id="quick-dropzone" class="quick-dropzone" tabindex="0" role="group" aria-label="貼上或拖曳截圖"><b>在此按 Ctrl＋V 貼上截圖</b><p>也可拖曳圖片，或選取多張檔案</p><input id="quick-files" type="file" multiple accept="image/png,image/jpeg,image/webp" aria-label="選取截圖"></div><div id="quick-file-list"></div><div id="quick-error" class="guild-form-error" role="alert"></div><div class="guild-actions"><button class="primary" data-g="quick-publish" ${S.busy?'disabled':''}>${S.busy?'上傳中…':'發布截圖至公會'}</button></div></section>`;paintQuickFiles();}
function paintQuickFiles(){const q=S.quick,slot=$('#quick-file-list');if(!q||!slot)return;slot.innerHTML=`<p class="guild-small">${q.existing.length+q.files.length}／10 張 · ${q.existing.length} 張已保存</p><div class="quick-previews">${q.existing.map(x=>`<div class="quick-saved">✓ 已保存：${esc(x.filename)}</div>`).join('')}${q.files.map((x,i)=>`<figure><img src="${esc(x.url)}" alt="待上傳截圖${i+1}"><figcaption>${esc(x.file.name)}<button class="soft-btn" type="button" data-g="quick-remove" data-i="${i}" ${S.busy?'disabled':''}>移除</button></figcaption></figure>`).join('')}</div>`;}
function addQuickFiles(files){if(!S.quick||S.busy)return;const result=pickQuickFiles(files,S.quick.files.length+S.quick.existing.length);S.quick.files.push(...result.accepted.map(file=>({file,url:URL.createObjectURL(file),path:null,uploaded:false})));if(result.accepted.length)S.dirty=true;paintQuickFiles();if($('#quick-error'))$('#quick-error').textContent=result.errors.join('；');}
async function publishQuick(){if(S.busy||!S.quick)return;const q=S.quick;if(!q.files.length&&!q.existing.length){$('#quick-error').textContent='請先貼上或選擇至少1張截圖';return;}S.busy=true;renderQuickEditor();
 try{
  if(!await verify())return;if(S.quick!==q)return;
  const title=q.title.trim()||`截圖快報 ${new Date().toLocaleDateString('zh-TW')}`;
  if(!q.id){const {data,error}=await db.from('gvg_guides').insert({guild_id:S.access.guild_id,author_id:S.user.id,title,summary:q.summary,status:'draft',build:screenshotBuild(0),video_url:''}).select().single();if(error)throw error;q.id=data.id;}
  for(const entry of [...q.files]){
   if(S.quick!==q)return;
   if(!await verify())return;
   const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[entry.file.type];entry.path??=`${S.access.guild_id}/${q.id}/${crypto.randomUUID()}.${ext}`;
   if(!entry.uploaded){const {error}=await db.storage.from('gvg-guides').upload(entry.path,entry.file,{contentType:entry.file.type,cacheControl:'0',upsert:false});if(error)throw error;entry.uploaded=true;}
   const {data:previous}=await db.from('gvg_attachments').select('*').eq('guide_id',q.id).eq('path',entry.path);
   let attachment=previous?.[0];if(!attachment){const {data,error}=await db.from('gvg_attachments').insert({guide_id:q.id,uploader_id:S.user.id,path:entry.path,filename:(entry.file.name||'截圖.'+ext).slice(0,160)}).select().single();if(error)throw error;attachment=data;}
   q.existing.push(attachment);q.files=q.files.filter(x=>x!==entry);URL.revokeObjectURL(entry.url);paintQuickFiles();
  }
  if(S.quick!==q)return;
  const {error}=await db.from('gvg_guides').update({title,summary:q.summary,status:'published',build:screenshotBuild(q.existing.length)}).eq('id',q.id).select().single();if(error)throw error;
  const id=q.id;S.dirty=false;releaseQuick();await loadGuild();await openGuide(id);toast('截圖已發布至公會');
 }catch(e){if(S.quick===q){$('#quick-error').textContent=errorText(e)+`；已保存${q.existing.length}張，未全部完成前不會公開新投稿，請重試。`;}}
 finally{S.busy=false;if(S.quick===q)root.querySelectorAll('[data-g="quick-publish"]').forEach(b=>{b.disabled=false;b.textContent='發布截圖至公會'});}
}
function renderQuickDetail(g,edit){root.innerHTML=`<section class="guild-detail"><div class="guild-topline"><a href="guild.html" data-g="back">← 公會攻略</a><div class="guild-actions">${edit?'<button class="soft-btn" data-g="edit">編輯截圖投稿</button><button class="soft-btn" data-g="delete">刪除投稿</button>':''}</div></div><span class="badge gold">公會截圖快報${g.status==='draft'?' · 尚未發布':''}</span><h1>${esc(g.title)}</h1><p class="guild-prose">${esc(g.summary)}</p><p class="guild-small">${esc(S.members.find(m=>m.user_id===g.author_id)?.nickname||'原公會成員')} · ${new Date(g.updated_at).toLocaleString('zh-TW')}</p><section class="guild-form-section"><h2>公會專用截圖</h2><div class="guild-images">${S.attachments.map(a=>`<figure><div class="guild-loading" id="image-${esc(a.id)}">載入圖片…</div><figcaption>${esc(a.filename)}${edit?` <button class="link-btn" data-g="image-delete" data-id="${esc(a.id)}">移除</button>`:''}</figcaption></figure>`).join('')}</div>${S.attachments.length?'':'<p>尚無已完成的截圖。可進入編輯補上圖片。</p>'}</section></section>`;}
async function loadImages(){const generation=S.generation,id=S.guide?.id;for(const a of S.attachments){
 const slot=$(`#image-${a.id}`);if(!slot)continue;
 const {data,error}=await db.storage.from('gvg-guides').download(a.path);
 if(generation!==S.generation||S.guide?.id!==id||S.view!=='detail')return;
 if(error){slot.textContent='圖片無法載入，請重新驗證後再試。';continue;}
 const url=URL.createObjectURL(data);S.urls.push(url);const img=document.createElement('img');img.src=url;img.alt=a.filename;slot.replaceChildren(img);slot.classList.remove('guild-loading');
 }}
async function uploadImage(file){
 if(!file||S.busy)return;if(file.size>5242880||!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('請選擇5MB以下的 PNG、JPG 或 WebP 圖片');
 S.busy=true;const input=$('#guild-upload');if(input)input.disabled=true;
 try{if(!await verify())return;const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];const path=`${S.access.guild_id}/${S.guide.id}/${crypto.randomUUID()}.${ext}`;
 const {error}=await db.storage.from('gvg-guides').upload(path,file,{contentType:file.type,cacheControl:'0',upsert:false});if(error)throw error;
 const {error:ae}=await db.from('gvg_attachments').insert({guide_id:S.guide.id,uploader_id:S.user.id,path,filename:file.name.slice(0,160)});
 if(ae){await db.storage.from('gvg-guides').remove([path]);throw ae;}
 await openGuide(S.guide.id);toast('截圖已上傳至公會私有空間');
 }catch(e){showError(e)}finally{S.busy=false;if(input)input.disabled=false;}}
async function action(b){const a=b.dataset.g;if(S.busy&&!['logout'].includes(a))return;
 try{
 if(a==='visual-select'){const f=b.closest('.visual-field'),select=f.querySelector('select');select.value=b.dataset.value;select.dispatchEvent(new Event('change',{bubbles:true}));return;}
 if(a==='login')return login();
 if(a==='logout'){if(S.dirty&&!confirm('攻略尚未儲存，確定登出？'))return;try{sessionStorage.removeItem('gvg-discord:'+S.user?.id)}catch{}clearPrivate();S.providerToken=null;S.user=null;authVersion++;await db.auth.signOut({scope:'local'});lockPage('已登出。');return;}
 if(a==='refresh'){if(await verify({force:true})){await loadGuild();render();}return;}
 if(!S.access||Date.parse(S.access.checked_until)<=Date.now()){clearPrivate();lockPage('公會資格驗證已到期，請重新驗證。');return;}
 if(a==='quick-new'){if(!['admin','editor'].includes(S.access.role))return;beginQuick();return;}
 if(a==='quick-publish')return publishQuick();
 if(a==='quick-remove'){const q=S.quick;if(!q||S.busy)return;const [removed]=q.files.splice(+b.dataset.i,1);if(removed)URL.revokeObjectURL(removed.url);S.dirty=true;paintQuickFiles();return;}
 if(a==='quick-cancel'){if(S.dirty&&!confirm('離開會捨棄尚未上傳的截圖，已保存部分仍留在草稿。確定離開？'))return;releaseQuick();S.dirty=false;S.view='list';await loadGuild();render();return;}
 if(a==='back'){if(S.dirty&&!confirm('離開會捨棄尚未儲存的內容，確定離開？'))return;S.edit=null;S.dirty=false;S.view='list';S.guide=null;releaseImages();await loadGuild();render();window.scrollTo({top:0});}
 else if(a==='new'){if(!['admin','editor'].includes(S.access.role))return;S.edit=blankGuide();S.heroTypes={};const preset=new URL(location.href).searchParams.get('enemy')?.split(',');if(preset?.length===3&&preset.every(id=>H.has(id)))S.edit.build.matchups[0].heroes=preset.map(id=>({id,form:'s6'}));S.view='edit';S.dirty=false;render();window.scrollTo({top:0});}
 else if(a==='mine'){S.mine=!S.mine;renderList();}
 else if(a==='reload'){await loadGuild();renderList();}
 else if(a==='reset-filter'){S.enemy=['','',''];Object.keys(S.heroTypes).filter(k=>k.startsWith('filter.')).forEach(k=>delete S.heroTypes[k]);renderList();}
 else if(a==='open')await openGuide(b.dataset.id);
 else if(a==='edit'){if(!canEdit(S.guide,S.user.id,S.access.role))return;if(S.guide.build.kind==='screenshots'){beginQuick(S.guide);return;}S.edit=structuredClone(S.guide);S.edit.build.queue??=[];S.edit.build.matchups.forEach(m=>{m.enemy_queue??=[];m.heroes.forEach(h=>h.row??='front')});S.heroTypes={};S.view='edit';S.dirty=false;releaseImages();render();window.scrollTo({top:0});}
 else if(a==='save')await saveGuide(b.dataset.status);
 else if(a==='set-select'){const i=+b.dataset.i;S.edit.build.heroes[i].set=b.dataset.value;stamp();renderEditor();$(`[data-set-index="${i}"] summary`)?.focus({preventScroll:true});}
 else if(a==='add-matchup'){S.edit.build.matchups.push(blankMatchup());stamp();renderEditor();}
 else if(a==='remove-matchup'){S.edit.build.matchups.splice(+b.dataset.i,1);Object.keys(S.heroTypes).filter(k=>k.startsWith('build.matchups.')).forEach(k=>delete S.heroTypes[k]);stamp();renderEditor();}
 else if(a==='ring-add'){const h=S.edit.build.heroes[+b.dataset.i];h.accessory_alternatives??=[];if(h.accessory_alternatives.length>=2)return;h.accessory_alternatives.push({accessory_kind:'any',accessory_rarity:'any',accessory_effect_1:'',accessory_effect_2:''});stamp();renderEditor();}
 else if(a==='ring-remove'){S.edit.build.heroes[+b.dataset.i].accessory_alternatives.splice(+b.dataset.j,1);stamp();renderEditor();}
 else if(a==='skill-toggle'){const queue=b.dataset.i==='general'?S.edit.build.queue:S.edit.build.matchups[+b.dataset.i].enemy_queue;const next=toggleReservation(queue,b.dataset.hero,b.dataset.skill,queueHeroes(b.dataset.i),K);if(next===queue&&queue.length>=MAX_RESERVATIONS)return toast(`技能預約最多${MAX_RESERVATIONS}手`);if(b.dataset.i==='general')S.edit.build.queue=next;else S.edit.build.matchups[+b.dataset.i].enemy_queue=next;stamp();const y=window.scrollY;renderEditor();const section=root.querySelector(`[data-queue-scope="${b.dataset.i}"]`);section?.querySelector(`[data-hero="${b.dataset.hero}"][data-skill="${b.dataset.skill}"]`)?.focus({preventScroll:true});window.scrollTo({top:y});}
 else if(a==='queue-remove'){(b.dataset.i==='general'?S.edit.build.queue:S.edit.build.matchups[+b.dataset.i].enemy_queue).splice(+b.dataset.j,1);stamp();renderEditor();}
 else if(a==='queue-down'){const q=(b.dataset.i==='general'?S.edit.build.queue:S.edit.build.matchups[+b.dataset.i].enemy_queue),j=+b.dataset.j;if(j>=q.length-1)return;[q[j],q[j+1]]=[q[j+1],q[j]];stamp();renderEditor();}
 else if(a==='queue-up'){const q=(b.dataset.i==='general'?S.edit.build.queue:S.edit.build.matchups[+b.dataset.i].enemy_queue),j=+b.dataset.j;if(j<=0)return;[q[j-1],q[j]]=[q[j],q[j-1]];stamp();renderEditor();}
 else if(a==='delete'){if(!confirm('確定刪除這篇攻略與回報？此操作無法復原。'))return;if(!await verify())return;for(const at of S.attachments){const {error}=await db.storage.from('gvg-guides').remove([at.path]);if(error)throw error;}const {error}=await db.from('gvg_guides').delete().eq('id',S.guide.id).select().single();if(error)throw error;S.guide=null;S.view='list';releaseImages();await loadGuild();render();toast('攻略已刪除');}
 else if(a==='image-delete'){if(!confirm('確定移除此張截圖？'))return;const at=S.attachments.find(x=>x.id===b.dataset.id);if(!at)return;const {error}=await db.storage.from('gvg-guides').remove([at.path]);if(error)throw error;const {error:ae}=await db.from('gvg_attachments').delete().eq('id',at.id).select().single();if(ae)throw ae;if(S.guide.build.kind==='screenshots'){const count=S.attachments.length-1;const {error:ge}=await db.from('gvg_guides').update({build:screenshotBuild(count),...(count===0?{status:'draft'}:{})}).eq('id',S.guide.id).select().single();if(ge)throw ge;}await openGuide(S.guide.id);}
 else if(a==='comment-delete'){if(!confirm('確定刪除此則回報？'))return;const {error}=await db.from('gvg_comments').delete().eq('id',b.dataset.id).select().single();if(error)throw error;await openGuide(S.guide.id);}
 }catch(e){showError(e);}
}
root.addEventListener('click',e=>{const b=e.target.closest('[data-g]');if(b){e.preventDefault();action(b)}});
root.addEventListener('input',e=>{
 if(e.target.id==='guild-search'){S.search=e.target.value;renderCards();return;}
 if(S.quick&&e.target.dataset.quick){S.quick[e.target.dataset.quick]=e.target.value;S.dirty=true;return;}
 if(!S.edit)return;
 if(e.target.dataset.path){setPath(S.edit,e.target.dataset.path,e.target.value);stamp();if(e.target.dataset.path==='build.pet.name'&&$('#selected-pet-art'))$('#selected-pet-art').innerHTML=petImage(e.target.value);}
 if(e.target.dataset.statHero!==undefined){const i=+e.target.dataset.statHero,key=e.target.dataset.statKey,h=S.edit.build.heroes[i];let s=h.stats.find(x=>x.key===key);if(!s){s={key,value:'',kind:'recommended'};h.stats.push(s)}s.value=e.target.value;stamp();}
});
root.addEventListener('change',e=>{
 if(e.target.dataset.rolePath){const path=e.target.dataset.rolePath,role=e.target.value;S.heroTypes[path]=role;if(path.startsWith('filter.')){const i=+path.split('.')[1];if(H.get(S.enemy[i])?.role_en!==role)S.enemy[i]='';renderList();return;}if(!S.edit)return;const h=getPath(S.edit,path);if(H.get(h.id)?.role_en!==role){h.id='';h.form='s6';}reconcileGuideQueues();stamp();renderEditor();return;}
 if(e.target.id==='quick-files'){addQuickFiles([...e.target.files]);e.target.value='';return;}
 if(e.target.id==='guild-upload')return uploadImage(e.target.files[0]);
 if(e.target.dataset.filterEnemy!==undefined){S.enemy[+e.target.dataset.filterEnemy]=e.target.value;renderCards();return;}
 if(!S.edit)return;
 if(e.target.dataset.path){setPath(S.edit,e.target.dataset.path,e.target.value);stamp();if(e.target.dataset.path==='build.pet.name'&&$('#selected-pet-art'))$('#selected-pet-art').innerHTML=petImage(e.target.value);}
 if(e.target.dataset.statKind!==undefined){const h=S.edit.build.heroes[+e.target.dataset.statKind],key=e.target.dataset.statKey;let s=h.stats.find(x=>x.key===key);if(!s){s={key,value:'',kind:e.target.value};h.stats.push(s)}else s.kind=e.target.value;stamp();}
 if(e.target.dataset.path&&(/\.row$|\.formation$|accessory_kind$|accessory_rarity$|accessory_effect_[12]$|attack_order$/.test(e.target.dataset.path)||e.target.closest('.visual-field'))&&!e.target.dataset.heroChange&&!e.target.dataset.enemyChange){renderEditor();}
 if(e.target.dataset.path&&/^build\.(heroes\.\d+|matchups\.\d+\.heroes\.\d+)\.form$/.test(e.target.dataset.path)){reconcileGuideQueues();renderEditor();}
 if(e.target.dataset.heroChange!==undefined){const h=S.edit.build.heroes[+e.target.dataset.heroChange],fs=[...new Set(D.skills.filter(s=>s.hero_id===h.id).map(s=>s.form))];h.form=fs.includes('s6')?'s6':fs[0]||'s6';reconcileGuideQueues();renderEditor();}
 if(e.target.dataset.enemyChange){const [i,j]=e.target.dataset.enemyChange.split(',').map(Number),h=S.edit.build.matchups[i].heroes[j],fs=[...new Set(D.skills.filter(s=>s.hero_id===h.id).map(s=>s.form))];h.form=fs.includes('s6')?'s6':fs[0]||'s6';reconcileGuideQueues();renderEditor();}
});
root.addEventListener('submit',async e=>{
 if(e.target.id!=='guild-comment-form')return;e.preventDefault();if(S.busy)return;const form=e.target,body=form.elements.body.value.trim(),result=form.elements.result.value;if(!body)return;S.busy=true;form.querySelector('button').disabled=true;
 try{if(!await verify())return;const {error}=await db.from('gvg_comments').insert({guide_id:S.guide.id,author_id:S.user.id,nickname:S.member.nickname,result,body});if(error)throw error;await openGuide(S.guide.id);toast('實戰回報已送出');}catch(err){showError(err)}finally{S.busy=false;if(form.isConnected)form.querySelector('button').disabled=false;}
});
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue='';}});
setInterval(async()=>{if(!S.user||document.hidden||Date.now()<retryAt||Date.now()-lastAttempt<15000)return;const previous=S.access?.role;if(await verify({silent:true})){if(!S.guild||previous!==S.access.role){await loadGuild().catch(showError);restoreEditor();render();}}},15000);
document.addEventListener('visibilitychange',async()=>{if(!document.hidden&&S.user){if(S.access&&Date.parse(S.access.checked_until)<=Date.now())suspendPrivate('正在恢復 Discord 驗證…');if(await verify({silent:true})){if(!S.guild){await loadGuild().catch(showError);restoreEditor();render();}await updatePresence();}}});
setInterval(()=>{if(S.access&&Date.parse(S.access.checked_until)<=Date.now()){suspendPrivate('正在重新驗證 Discord，系統將自動重試。尚未儲存的內容暫留本頁，請勿關閉。');}},5000);
async function start(session){const run=++authVersion;
 if(!session){clearPrivate();S.user=null;S.providerToken=null;providerUser=null;lockPage();return;}
 S.user=session.user;rememberToken(session);
 if(!await verify()||run!==authVersion)return;
 try{await loadGuild();if(run===authVersion)render();}catch(e){clearPrivate();lockPage(errorText(e));}
}
try{
 try{const settings=await fetch(SUPABASE_URL+'/auth/v1/settings',{headers:{apikey:SUPABASE_PUBLISHABLE_KEY}});if(settings.ok){const cfg=await settings.json();S.setupPending=cfg.external?.discord===false;}}catch{}
 const response=await fetch('app-data.json');if(!response.ok)throw new Error('角色資料無法載入');D=await response.json();const catResponse=await fetch('guide-catalog.json?v=0.9.0');if(!catResponse.ok)throw new Error('選單資料無法載入，請重新整理');C=await catResponse.json();const skillResponse=await fetch('skill-catalog.json?v=0.9.0');if(!skillResponse.ok)throw new Error('技能圖示資料無法載入，請重新整理');K=await skillResponse.json();heroes=D.heroes.filter(h=>h.released_in_source).sort((a,b)=>a.name_tw.localeCompare(b.name_tw,'zh-Hant'));H=new Map(heroes.map(h=>[h.hero_id,h]));pets=availableLegendaryPets(C).map(p=>p.name_tw);sets=C.sets.map(s=>s.name);accessories=[...new Set(D.guildwar_hero_builds.flatMap(b=>[...b.accA_tw_json,...b.accB_tw_json]))];
 const enemy=new URL(location.href).searchParams.get('enemy')?.split(',');if(enemy?.length===3&&enemy.every(id=>H.has(id)))S.enemy=enemy;
 db.auth.onAuthStateChange((event,session)=>{if(event==='INITIAL_SESSION'||event==='SIGNED_IN'||event==='SIGNED_OUT'){setTimeout(()=>{if(event==='SIGNED_IN'&&S.user?.id===session?.user.id&&S.guild){rememberToken(session);return;}start(session)},0);}});
}catch(e){lockPage(errorText(e));}

// Keep the icon dropdown operable with keyboard as well as touch.
root.addEventListener('keydown',e=>{const picker=e.target.closest('.set-picker,.visual-picker');if(!picker)return;const opts=[...picker.querySelectorAll('[role="option"]')];if(e.key==='Escape'){picker.open=false;picker.querySelector('summary').focus();e.preventDefault();return;}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();picker.open=true;let i=opts.indexOf(document.activeElement);if(e.key==='Home')i=0;else if(e.key==='End')i=opts.length-1;else if(i<0)i=e.key==='ArrowDown'?0:opts.length-1;else i=(i+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length;opts[i]?.focus();}});
root.addEventListener('click',e=>{const active=e.target.closest('.set-picker,.visual-picker');root.querySelectorAll('.set-picker[open],.visual-picker[open]').forEach(p=>{if(p!==active)p.open=false;});});

document.addEventListener('paste',e=>{if(!S.quick||S.view!=='quick')return;const files=[...(e.clipboardData?.items||[])].filter(x=>x.kind==='file').map(x=>x.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();addQuickFiles(files);}});
root.addEventListener('dragover',e=>{if(S.quick&&S.view==='quick'){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
root.addEventListener('drop',e=>{if(S.quick&&S.view==='quick'){e.preventDefault();addQuickFiles([...e.dataTransfer.files]);}});
